// TestComposeReviewPrompt_AppendsScopeClause locks the format and
// presence rules for the scope clause: empty SHA omits it; SHA-only
// renders without the branch label; branch+SHA renders the full clause
// after the base prompt.
func TestComposeReviewPrompt_AppendsScopeClause(t *testing.T) {
	t.Parallel()
	cfg := settings.ReviewConfig{Skills: []string{"/review"}}
	tests := []struct {
		name           string
		scope          reviewPromptScope
		wantContains   []string
		wantNotContain []string
	}{
		{
			name:           "no SHA, no clause",
			scope:          reviewPromptScope{Branch: "main"},
			wantNotContain: []string{"Review scope:"},
		},
		{
			name:         "SHA only, no branch label",
			scope:        reviewPromptScope{StartingSHA: "abc123"},
			wantContains: []string{"Review scope:", "HEAD was `abc123`", "git diff abc123..HEAD"},
			wantNotContain: []string{
				"on branch ``", // would imply we rendered an empty branch label
			},
		},
		{
			name:         "branch + SHA",
			scope:        reviewPromptScope{Branch: "hackathon-slides", StartingSHA: "9deeffa"},
			wantContains: []string{"on branch `hackathon-slides`", "HEAD was `9deeffa`"},
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			t.Parallel()
			got := composeReviewPrompt(cfg, "", tt.scope)
			for _, want := range tt.wantContains {
				if !strings.Contains(got, want) {
					t.Errorf("missing %q in:\n%s", want, got)
				}
			}
			for _, unwant := range tt.wantNotContain {
				if strings.Contains(got, unwant) {
					t.Errorf("unexpected %q in:\n%s", unwant, got)
				}
			}
		})
	}
}

