		promptForRunContextFn: func(_ context.Context) (string, error) {
			called = true
			return "focus on auth refactor", nil
		},
	}

	reviewCmd := newReviewCmdWithDeps(deps)
	if err := reviewCmd.Execute(); err != nil {
		t.Fatalf("execute: %v", err)
	}
