	if len(gotPrompts) != 2 {
		t.Fatalf("expected 2 prompts, got %d", len(gotPrompts))
	}
	want := "always flag side effects\n\nFor this review: focus on auth"
	for i, prompt := range gotPrompts {
		if prompt != want {
			t.Errorf("task[%d].Prompt =\n%q\nwant:\n%q", i, prompt, want)
		}
	}
}

