// aligned by index, sharing the same tees the orchestrator feeds.
func newReviewTUIModel(tasks []MultiAgentTask, onCancel func(), buffers []*agentBuffer) reviewTUIModel {
	rows := make([]rowState, len(tasks))
	for i, t := range tasks {
